using System;
using System.Collections.Generic;
using System.Linq;

// Short, practical routes. Ratings describe relative risk and travel time, not a guarantee of safety or drops.
public sealed class FarmingRoute {
 public int Act, Safety, Rank;
 public string Name, Goals, Difficulty, SuggestedLevel, Start, Targets, LookFor, Focus, Caution, GuideEntry;
 public FarmingRoute(int act,int safety,int rank,string name,string goals,string difficulty,string suggestedLevel,string start,string targets,string lookFor,string focus,string caution,string guideEntry){Act=act;Safety=safety;Rank=rank;Name=name;Goals=goals;Difficulty=difficulty;SuggestedLevel=suggestedLevel;Start=start;Targets=targets;LookFor=lookFor;Focus=focus;Caution=caution;GuideEntry=guideEntry;}
 public override string ToString(){return "ACT "+Act+"  •  "+Name;}
 public bool Supports(string goal){return goal=="Any goal"||Goals.IndexOf(goal,StringComparison.OrdinalIgnoreCase)>=0;}
 public string Details(){return "ACT "+Act+"  •  "+Goals.ToUpperInvariant()+"\r\n\r\nWHEN TO RUN\r\n"+Difficulty+"  •  Suggested character level: "+SuggestedLevel+"\r\n\r\nSTART\r\n"+Start+"\r\n\r\nNOTABLE TARGETS\r\n"+Targets+"\r\n\r\nWHAT TO LOOK FOR\r\n"+LookFor+"\r\n\r\nWHY RUN IT\r\n"+Focus+"\r\n\r\nSAFETY\r\n"+Caution+"\r\n\r\nGUIDE BOOK\r\nOpen "+GuideEntry+" for the related quest and area notes.";}
}

