 public static List<FarmingRoute> Find(int act,string goal,int safety){return Find(Routes,act,goal,safety);}
 public static List<FarmingRoute> Find(IEnumerable<FarmingRoute> routes,int act,string goal,int safety){return routes.Where(r=>(act==0||r.Act==act)&&r.Safety<=safety&&r.Supports(goal)).OrderBy(r=>r.Safety).ThenBy(r=>r.Act).ThenBy(r=>r.Rank).ToList();}
}
